import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";

const text = spawnSync(process.execPath, ["src/report.ts"], { encoding: "utf8" });
assert.equal(text.status, 0);
assert.match(text.stdout ?? "", /status: ok/);
const json = spawnSync(process.execPath, ["src/report.ts", "--format", "json"], { encoding: "utf8" });
assert.equal(json.status, 0);
assert.match(json.stdout ?? "", /\{"status":"ok","count":1\}/);
console.log("OK: report");
